const LocalHistory=(()=>{const DB='signal-web-local-history',STORE='messages',PAGE=40;let dbPromise;const account=()=>String(state.me?.id||'');const conversationKey=id=>`${account()}:${Number(id)}`;const recordKey=(conversationID,messageID)=>`${conversationKey(conversationID)}:${messageID}`;const sortKey=m=>`${String(new Date(m.created_at).getTime()).padStart(16,'0')}:${String(m.id).padStart(16,'0')}`;function db(){if(!dbPromise)dbPromise=new Promise((resolve,reject)=>{const request=indexedDB.open(DB,1);request.onupgradeneeded=()=>{const store=request.result.createObjectStore(STORE,{keyPath:'key'});store.createIndex('conversation','conversation',{unique:false})};request.onsuccess=()=>resolve(request.result);request.onerror=()=>reject(request.error)});return dbPromise}async function write(mode,work){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction(STORE,mode),store=tx.objectStore(STORE);work(store,tx);tx.oncomplete=()=>resolve();tx.onerror=()=>reject(tx.error);tx.onabort=()=>reject(tx.error)})}async function put(message,read=false){const record={key:recordKey(message.conversation_id,message.id),conversation:conversationKey(message.conversation_id),sort:sortKey(message),read:read||message.sender_id===state.me?.id,message};await write('readwrite',store=>store.put(record))}async function page(conversationID,before='',limit=PAGE){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction(STORE,'readonly'),index=tx.objectStore(STORE).index('conversation'),items=[];const request=index.openCursor(IDBKeyRange.only(conversationKey(conversationID)),'prev');request.onsuccess=()=>{const cursor=request.result;if(!cursor)return resolve(items.reverse());const item=cursor.value;if((!before||item.sort<before)&&items.length<limit)items.push(item);if(items.length>=limit)return resolve(items.reverse());cursor.continue()};request.onerror=()=>reject(request.error)})}async function summaries(conversationIDs){const result=new Map;await Promise.all(conversationIDs.map(async id=>{const database=await db();const summary=await new Promise((resolve,reject)=>{const tx=database.transaction(STORE,'readonly'),index=tx.objectStore(STORE).index('conversation'),request=index.openCursor(IDBKeyRange.only(conversationKey(id)),'prev');let latest=null,unread=0;request.onsuccess=()=>{const cursor=request.result;if(!cursor)return resolve({latest,unread});const item=cursor.value;if(!latest)latest=item.message;if(!item.read&&item.message.sender_id!==state.me?.id)unread++;cursor.continue()};request.onerror=()=>reject(request.error)});result.set(Number(id),summary)}));return result}async function updateConversation(conversationID,updater){await write('readwrite',store=>{const request=store.index('conversation').openCursor(IDBKeyRange.only(conversationKey(conversationID)));request.onsuccess=()=>{const cursor=request.result;if(!cursor)return;const value=cursor.value,updated=updater(value);if(updated)cursor.update(value);cursor.continue()}})}async function deleteIfSender(conversationID,messageID,senderID){const database=await db();return new Promise((resolve,reject)=>{const tx=database.transaction(STORE,'readwrite'),store=tx.objectStore(STORE),request=store.get(recordKey(conversationID,messageID));let removed=false;request.onsuccess=()=>{if(request.result?.message?.sender_id===senderID){store.delete(request.result.key);removed=true}};tx.oncomplete=()=>resolve(removed);tx.onerror=()=>reject(tx.error)})}return{PAGE,put,page,summaries,markRead:id=>updateConversation(id,item=>{item.read=true;return true}),delete:message=>write('readwrite',store=>store.delete(recordKey(message.conversation_id,message.id))),deleteIfSender,clear:id=>write('readwrite',store=>{const request=store.index('conversation').openKeyCursor(IDBKeyRange.only(conversationKey(id)));request.onsuccess=()=>{const cursor=request.result;if(cursor){store.delete(cursor.primaryKey);cursor.continue()}}}),sortKey}})();
// Keep a bounded localStorage mirror so browsers that disable, evict, or fail
// IndexedDB do not lose a just-sent message after refresh. IndexedDB remains the
// primary, unbounded history store; the mirror is a resilient recent-history tier.
const LocalHistoryMirror=(()=>{const PREFIX='signalHistory:';const key=id=>`${PREFIX}${state.me?.id||''}:${Number(id)}`;const read=id=>{try{const value=JSON.parse(localStorage.getItem(key(id))||'[]');return Array.isArray(value)?value:[]}catch{return[]}};const save=(id,records)=>{let kept=records.sort((a,b)=>a.sort.localeCompare(b.sort)).slice(-300);while(kept.length){try{const json=JSON.stringify(kept);if(json.length>1500000){kept=kept.slice(Math.ceil(kept.length/2));continue}localStorage.setItem(key(id),json);return}catch{kept=kept.slice(Math.ceil(kept.length/2))}}try{localStorage.removeItem(key(id))}catch{}};const put=(message,readState)=>{const records=read(message.conversation_id).filter(item=>String(item.message?.id)!==String(message.id));records.push({sort:LocalHistory.sortKey(message),read:readState||message.sender_id===state.me?.id,message});save(message.conversation_id,records)};return{read,put,markRead:id=>save(id,read(id).map(item=>({...item,read:true}))),delete:message=>save(message.conversation_id,read(message.conversation_id).filter(item=>String(item.message?.id)!==String(message.id))),deleteIfSender:(conversationID,messageID,senderID)=>{const records=read(conversationID),found=records.some(item=>String(item.message?.id)===String(messageID)&&item.message?.sender_id===senderID);if(found)save(conversationID,records.filter(item=>String(item.message?.id)!==String(messageID)));return found},clear:id=>{try{localStorage.removeItem(key(id))}catch{}}}})();
const IndexedHistory={put:LocalHistory.put,page:LocalHistory.page,summaries:LocalHistory.summaries,markRead:LocalHistory.markRead,delete:LocalHistory.delete,deleteIfSender:LocalHistory.deleteIfSender,clear:LocalHistory.clear};
const NativeHistory=window.signalDesktop?.history;
LocalHistory.put=async(message,readState=false)=>{const read=readState||message.sender_id===state.me?.id,sort=LocalHistory.sortKey(message);LocalHistoryMirror.put(message,read);const writes=[IndexedHistory.put(message,read)];if(NativeHistory)writes.push(NativeHistory.put({accountId:state.me.id,message,read,sort}));const results=await Promise.allSettled(writes);results.filter(result=>result.status==='rejected').forEach(result=>console.warn('local message write failed',result.reason))};
LocalHistory.page=async(conversationID,before='',limit=LocalHistory.PAGE)=>{const reads=[IndexedHistory.page(conversationID,before,limit)];if(NativeHistory)reads.push(NativeHistory.page({accountId:state.me.id,conversationId:conversationID,before,limit}));const settled=await Promise.allSettled(reads),merged=new Map;for(const item of [...settled.flatMap(result=>result.status==='fulfilled'?result.value:[]),...LocalHistoryMirror.read(conversationID)])if(!before||item.sort<before)merged.set(String(item.message.id),item);settled.filter(result=>result.status==='rejected').forEach(result=>console.warn('local history read failed',result.reason));return[...merged.values()].sort((a,b)=>a.sort.localeCompare(b.sort)).slice(-limit)};
LocalHistory.summaries=async conversationIDs=>{let indexed=new Map,native={};try{indexed=await IndexedHistory.summaries(conversationIDs)}catch(error){console.warn('IndexedDB summary read failed',error)}if(NativeHistory)try{native=await NativeHistory.summaries({accountId:state.me.id,conversationIds:conversationIDs})}catch(error){console.warn('Windows history summary read failed',error)}const result=new Map;for(const id of conversationIDs){const records=LocalHistoryMirror.read(id),sources=[indexed.get(Number(id)),native[id]],latest=[...records.map(item=>item.message),...sources.map(item=>item?.latest).filter(Boolean)].sort((a,b)=>new Date(a.created_at)-new Date(b.created_at)).at(-1)||null,unread=Math.max(records.filter(item=>!item.read&&item.message?.sender_id!==state.me?.id).length,...sources.map(item=>item?.unread||0));result.set(Number(id),{latest,unread})}return result};
LocalHistory.markRead=async id=>{LocalHistoryMirror.markRead(id);const writes=[IndexedHistory.markRead(id)];if(NativeHistory)writes.push(NativeHistory.markRead({accountId:state.me.id,conversationId:id}));(await Promise.allSettled(writes)).filter(result=>result.status==='rejected').forEach(result=>console.warn('local read-state update failed',result.reason))};
LocalHistory.delete=async message=>{LocalHistoryMirror.delete(message);const writes=[IndexedHistory.delete(message)];if(NativeHistory)writes.push(NativeHistory.delete({accountId:state.me.id,conversationId:message.conversation_id,messageId:message.id}));(await Promise.allSettled(writes)).filter(result=>result.status==='rejected').forEach(result=>console.warn('local message delete failed',result.reason))};
LocalHistory.deleteIfSender=async(conversationID,messageID,senderID)=>{const mirrored=LocalHistoryMirror.deleteIfSender(conversationID,messageID,senderID),writes=[IndexedHistory.deleteIfSender(conversationID,messageID,senderID)];if(NativeHistory)writes.push(NativeHistory.deleteIfSender({accountId:state.me.id,conversationId:conversationID,messageId:messageID,senderId:senderID}));const settled=await Promise.allSettled(writes);settled.filter(result=>result.status==='rejected').forEach(result=>console.warn('local synchronized delete failed',result.reason));return mirrored||settled.some(result=>result.status==='fulfilled'&&result.value)};
