let toastTimer;function toast(message,type='success'){const el=$('#toast');el.textContent=message;el.className=`toast ${type} show`;clearTimeout(toastTimer);toastTimer=setTimeout(()=>el.classList.remove('show'),2600)}
async function api(path,opt={}){opt.headers={...(opt.headers||{}),'Content-Type':'application/json',Authorization:`Bearer ${state.token}`};const r=await fetch('/api'+path,opt);if(r.status===204)return null;const j=await r.json().catch(()=>({}));if(!r.ok)throw Error(j.error||'请求失败');return j}
function initials(s){return (s||'?').slice(0,2).toUpperCase()} function esc(s){const d=document.createElement('div');d.textContent=s;return d.innerHTML}
function vapidBytes(value){const padded=(value+'='.repeat((4-value.length%4)%4)).replace(/-/g,'+').replace(/_/g,'/');return Uint8Array.from(atob(padded),c=>c.charCodeAt(0))}
async function syncPushSubscription(){state.pushEnabled=false;if(!('serviceWorker'in navigator)||!('PushManager'in window)||!('Notification'in window)||Notification.permission!=='granted'){updateNotificationButton();return false}const config=await api('/push/config');if(!config.enabled){updateNotificationButton();return false}const registration=await navigator.serviceWorker.ready;let subscription=await registration.pushManager.getSubscription();if(!subscription)subscription=await registration.pushManager.subscribe({userVisibleOnly:true,applicationServerKey:vapidBytes(config.public_key)});await api('/push/subscriptions',{method:'POST',body:JSON.stringify(subscription.toJSON())});state.pushEnabled=true;updateNotificationButton();return true}
