function insertEmoji(emoji){const input=$('#message'),start=input.selectionStart??input.value.length,end=input.selectionEnd??start;input.value=input.value.slice(0,start)+emoji+input.value.slice(end);input.selectionStart=input.selectionEnd=start+emoji.length;input.focus();emojiSets.最近=[emoji,...emojiSets.最近.filter(x=>x!==emoji)].slice(0,24);localStorage.signalRecentEmoji=JSON.stringify(emojiSets.最近)}
function renderEmojiPanel(category='最近'){const values=category==='最近'&&!emojiSets.最近.length?emojiSets.笑脸.slice(0,24):emojiSets[category];$('#emojiPanel').innerHTML=`<div class="emojiTabs">${Object.keys(emojiSets).map(x=>`<button type="button" class="emojiTab ${x===category?'active':''}" data-emoji-tab="${x}">${x}</button>`).join('')}</div><div class="emojiGrid">${values.map(x=>`<button type="button" class="emojiChoice" data-emoji="${x}">${x}</button>`).join('')}</div>`;document.querySelectorAll('[data-emoji-tab]').forEach(x=>x.onclick=()=>renderEmojiPanel(x.dataset.emojiTab));document.querySelectorAll('[data-emoji]').forEach(x=>x.onclick=()=>{insertEmoji(x.dataset.emoji);renderEmojiPanel(category)})}
function clearImageDraft(){state.imageDraft=null;if(state.imageDraftURL)URL.revokeObjectURL(state.imageDraftURL);state.imageDraftURL='';$('#imageInput').value='';$('#imageDraft').hidden=true;$('#imageDraftPreview').removeAttribute('src')}
function chooseImage(file){const allowed=['image/jpeg','image/png','image/webp','image/gif'];if(!file)return;if(!allowed.includes(file.type)){toast('仅支持 JPG、PNG、WebP、GIF 图片','error');return}if(file.size>8*1024*1024){toast('图片不能超过 8MB','error');return}clearImageDraft();state.imageDraft=file;state.imageDraftURL=URL.createObjectURL(file);$('#imageDraftPreview').src=state.imageDraftURL;$('#imageDraftName').textContent=`${file.name} · ${(file.size/1024/1024).toFixed(1)}MB`;$('#imageDraft').hidden=false}
async function uploadEncryptedAttachment(cipher,conversationID){const r=await fetch(`/api/conversations/${conversationID}/attachments`,{method:'POST',headers:{Authorization:`Bearer ${state.token}`,'Content-Type':'application/octet-stream'},body:cipher});const result=await r.json().catch(()=>({}));if(!r.ok)throw Error(result.error||'图片上传失败');return result}
async function deleteUnsentAttachment(id,conversationID){if(!id)return;await fetch(`/api/conversations/${conversationID}/attachments/${id}`,{method:'DELETE',headers:{Authorization:`Bearer ${state.token}`}}).catch(()=>{})}
function revokeMessageImages(){for(const url of state.objectURLs)URL.revokeObjectURL(url);state.objectURLs.clear()}
function showImageViewer(url,name){$('#imageViewerContent').src=url;$('#imageViewerName').textContent=name||'图片';$('#imageViewer').hidden=false}
function hideImageViewer(){$('#imageViewer').hidden=true;$('#imageViewerContent').removeAttribute('src')}
async function loadMessageImage(wrap,metadata,conversationID){try{if(!metadata?.id||!['image/jpeg','image/png','image/webp','image/gif'].includes(metadata.mime))throw Error('图片格式无效');const r=await fetch(`/api/conversations/${conversationID}/attachments/${metadata.id}`,{headers:{Authorization:`Bearer ${state.token}`}});if(!r.ok)throw Error('图片下载失败');const clear=await E2EE.decryptAttachment(await r.arrayBuffer(),metadata);if(metadata.size&&clear.byteLength!==metadata.size)throw Error('图片完整性校验失败');const url=URL.createObjectURL(new Blob([clear],{type:metadata.mime}));if(!wrap.isConnected){URL.revokeObjectURL(url);return}state.objectURLs.add(url);const img=document.createElement('img');img.className='messageImage';img.src=url;img.alt=metadata.name||'加密图片';img.loading='lazy';img.onclick=()=>showImageViewer(url,metadata.name);wrap.replaceChildren(img)}catch(e){wrap.innerHTML=`<div class="imageLoading">⚠ ${esc(e.message)}</div>`}}
$('#toggle').onclick=()=>{state.register=!state.register;$('#auth').classList.toggle('registering',state.register);$('#toggle').textContent=state.register?'已有账号？登录':'没有账号？注册';$('#authForm button:not(.ghost)').textContent=state.register?'注册':'登录'};
$('#authForm').onsubmit=async e=>{e.preventDefault();$('#authErr').textContent='';const submit=$('#authForm button:not(.ghost)');submit.disabled=true;try{const wasRegister=state.register;const body={username:$('#username').value,password:$('#password').value,display_name:$('#display').value,about:$('#about').value};const x=await api(wasRegister?'/register':'/login',{method:'POST',body:JSON.stringify(body)});state.token=x.token;localStorage.token=x.token;await start(body.password);toast(wasRegister?'注册成功，资料已建立':'登录成功')}catch(e){$('#authErr').textContent=e.message;toast(e.message,'error')}finally{submit.disabled=false}};
function renderMyProfile(){$('#myName').textContent=state.me.display_name;$('#myUsername').textContent='@'+state.me.username;$('#myAvatar').textContent=initials(state.me.display_name)}
async function start(password=''){try{if(!window.isSecureContext||!crypto.subtle)throw Error('端到端加密要求使用 HTTPS 安全连接');state.me=await api('/me');const keys=await E2EE.init(state.me.username,state.me.public_key,state.me.key_backup,state.me.pq_public_key,state.me.pq_key_backup,password);if(keys.created)await api('/me/key',{method:'PUT',body:JSON.stringify({public_key:keys.publicKey,key_backup:keys.keyBackup,password,replace:keys.replace})});if(keys.pqCreated)await api('/me/pq-key',{method:'PUT',body:JSON.stringify({public_key:keys.pqPublicKey,key_backup:keys.pqKeyBackup,password})});state.me.public_key=keys.publicKey;state.me.pq_public_key=keys.pqPublicKey;$('#auth').hidden=true;$('#app').hidden=false;renderMyProfile();updateNotificationButton();updateInstallButton();await Promise.all([loadChats(),loadFriends()]);connect();await restoreLaunchConversation();if(keys.pqNeedsPassword)toast('重新登录后将自动启用抗量子混合加密','error');if('Notification'in window&&Notification.permission==='granted')syncPushSubscription().catch(()=>updateNotificationButton())}catch(e){localStorage.removeItem('token');state.token='';$('#authErr').textContent=e.message;toast(e.message,'error');throw e}}
function userInfo(u){return `<div class="avatar">${esc(initials(u.display_name))}</div><div class="friendInfo"><b>${esc(u.display_name)}</b><small>@${esc(u.username)}${u.about?' · '+esc(u.about):''}</small></div>`}
async function loadFriends(){const [friends,requests]=await Promise.all([api('/friends'),api('/friend-requests')]);state.friends=friends;state.requests=requests;renderFriends($('#search').value);$('#requestBadge').hidden=!requests.length;$('#requestBadge').textContent=requests.length||''}
function renderFriends(filter=''){const q=filter.trim().toLowerCase(),friends=state.friends.filter(x=>!q||`${x.display_name} ${x.username} ${x.about}`.toLowerCase().includes(q));$('#friends').innerHTML=friends.map(x=>`<div class="friendRow" data-friend-chat="${x.id}">${userInfo(x)}<div class="friendActions"><button type="button" title="开始聊天">◉</button><button type="button" class="reject" data-remove-friend="${x.id}" title="删除好友">×</button></div></div>`).join('');$('#friendEmpty').hidden=!!friends.length;$('#friendRequests').innerHTML=state.requests.map(x=>`<div class="requestRow">${userInfo(x)}<div class="friendActions"><button type="button" data-accept-friend="${x.id}">接受</button><button type="button" class="reject" data-remove-friend="${x.id}">拒绝</button></div></div>`).join('');$('#requestSection').hidden=!state.requests.length;document.querySelectorAll('[data-friend-chat]').forEach(x=>x.onclick=e=>{if(!e.target.closest('[data-remove-friend]'))createDirect(+x.dataset.friendChat)});document.querySelectorAll('[data-accept-friend]').forEach(x=>x.onclick=()=>acceptFriend(+x.dataset.acceptFriend));document.querySelectorAll('[data-remove-friend]').forEach(x=>x.onclick=e=>{e.stopPropagation();removeFriend(+x.dataset.removeFriend)})}
function setSideView(view){state.sideView=view;document.querySelectorAll('[data-side-view]').forEach(x=>x.classList.toggle('active',x.dataset.sideView===view));$('#chatView').hidden=view!=='chats';$('#friendView').hidden=view!=='friends';$('#search').placeholder=view==='friends'?'搜索好友':'搜索消息';$('#search').value='';if(view==='friends')renderFriends();else renderChats()}
async function searchUsers(q){if(!q.trim()){$('#friendResults').innerHTML='<div class="listEmpty">输入信息开始查找</div>';return}state.users=await api('/users?q='+encodeURIComponent(q));$('#friendResults').innerHTML=state.users.length?state.users.map(u=>{const labels={none:'添加',outgoing:'取消申请',incoming:'去确认',friend:'发消息'};return `<div class="searchUser">${userInfo(u)}<button type="button" class="relationButton ${u.relationship}" data-user-action="${u.id}" data-relation="${u.relationship}">${labels[u.relationship]||'添加'}</button></div>`}).join(''):'<div class="listEmpty">没有找到用户</div>';document.querySelectorAll('[data-user-action]').forEach(x=>x.onclick=()=>userRelationshipAction(+x.dataset.userAction,x.dataset.relation))}
async function userRelationshipAction(id,relation){if(relation==='none'){try{await api('/friend-requests',{method:'POST',body:JSON.stringify({user_id:id})});toast('好友申请已发送');await searchUsers($('#friendSearch').value)}catch(e){toast(e.message,'error')}}else if(relation==='friend'){$('#friendDialog').close();createDirect(id)}else if(relation==='incoming'){$('#friendDialog').close();setSideView('friends')}else if(confirm('确定取消这条好友申请？')){try{await api(`/friends/${id}`,{method:'DELETE'});await searchUsers($('#friendSearch').value);toast('好友申请已取消')}catch(e){toast(e.message,'error')}}}
async function acceptFriend(id){try{await api(`/friend-requests/${id}/accept`,{method:'PUT'});await loadFriends();toast('已添加为好友')}catch(e){toast(e.message,'error')}}
async function removeFriend(id){const pending=state.requests.some(x=>x.id===id);if(!confirm(pending?'拒绝这条好友申请？':'确定删除该好友？现有聊天记录不会删除。'))return;try{await api(`/friends/${id}`,{method:'DELETE'});await loadFriends();toast(pending?'已拒绝好友申请':'好友已删除')}catch(e){toast(e.message,'error')}}
function refreshUnreadIndicators(){const unread=state.chats.reduce((n,x)=>n+(x.unread||0),0);document.title=unread?`(${unread}) Signal Web`:'Signal Web';updateAppBadge(unread)}
function clearUnreadLocal(id){const chat=state.chats.find(x=>x.id===id);if(chat)chat.unread=0;document.querySelector(`.chat[data-id="${id}"] .badge`)?.remove();refreshUnreadIndicators();LocalHistory.markRead(id).catch(e=>console.warn('local read update failed',e))}
async function syncConversationRead(id,refresh=true){if(!id)return;clearUnreadLocal(id);try{await api(`/conversations/${id}/read`,{method:'POST'})}catch(e){console.warn('read sync failed',e)}if(refresh)await loadChats()}
function scheduleConversationRead(id){if(!id)return;clearUnreadLocal(id);clearTimeout(readTimers.get(id));readTimers.set(id,setTimeout(()=>{readTimers.delete(id);if(state.active===id&&!document.hidden)syncConversationRead(id)},180))}
