async function handleConversationMenuAction(event,chat,button){event.stopPropagation();const action=button.dataset.chatAction;if(action==='mute-menu'){conversationMenu.classList.toggle('submenuOpen');return}hideConversationMenu();if(action==='clear'){await clearConversationHistory(chat.id);return}if(action==='delete'){await deleteConversation(chat.id);return}try{const payload={action};if(action==='mute')payload.mute_seconds=Number(button.dataset.seconds);await api(`/conversations/${chat.id}/state`,{method:'PUT',body:JSON.stringify(payload)});const labels={mark_unread:'已标记为未读',pin:'已置顶聊天',unpin:'已取消置顶',archive:'已存档',unarchive:'已移出存档',mute:'已静音通知',unmute:'已恢复通知'};await loadChats();toast(labels[action]||'会话已更新')}catch(e){toast(e.message,'error')}}
async function clearConversationHistory(id){if(!confirm('确定清除双方设备上的全部本地聊天记录？\n\n在线设备会立即同步清除；未在线设备将在下次收到同步事件前保留其本地副本。'))return;try{await api(`/conversations/${id}/messages`,{method:'DELETE'});await LocalHistory.clear(id);if(state.active===id){revokeMessageImages();$('#messages').innerHTML='';state.messagePayloads.clear();state.visibleMessages=[];state.historyDone=true;clearReplyDraft();hideMessageMenu();state.lastMessageDay=''}await loadChats();toast('本地聊天记录已清除')}catch(e){toast(e.message,'error')}}
function messageSummary(payload,limit=140){const text=(payload?.body||'').trim().replace(/\s+/g,' ');if(text)return text.length>limit?text.slice(0,limit)+'…':text;return payload?.attachment?'📷 图片':'消息'}
