async function forwardMessageTo(conversationID,button){const entry=state.forwardMessage;if(!entry||button.disabled)return;button.disabled=true;let uploadedID='';try{const members=await api(`/conversations/${conversationID}/members`);let attachment=null;if(entry.payload.attachment){toast('正在重新加密图片…');const source=await fetch(`/api/conversations/${entry.message.conversation_id}/attachments/${entry.payload.attachment.id}`,{headers:{Authorization:`Bearer ${state.token}`}});if(!source.ok)throw Error('原图片已不存在');const clear=await E2EE.decryptAttachment(await source.arrayBuffer(),entry.payload.attachment);if(entry.payload.attachment.size&&clear.byteLength!==entry.payload.attachment.size)throw Error('图片完整性校验失败');const file=new File([clear],entry.payload.attachment.name||'转发图片',{type:entry.payload.attachment.mime});const encrypted=await E2EE.encryptAttachment(file),uploaded=await uploadEncryptedAttachment(encrypted.cipher,conversationID);uploadedID=uploaded.id;attachment={id:uploaded.id,...encrypted.metadata}}const body=await E2EE.encrypt(entry.payload.body||'',conversationID,members,attachment,null);await api(`/conversations/${conversationID}/messages`,{method:'POST',body:JSON.stringify({body})});uploadedID='';$('#forwardDialog').close();state.forwardMessage=null;toast('消息已转发')}catch(e){await deleteUnsentAttachment(uploadedID,conversationID);toast(e.message,'error');button.disabled=false}}
async function deleteSingleMessage(entry,scope){const all=scope==='all',prompt=all?'确定撤回这条消息？在线设备会同步删除本地副本。':'确定从本机删除这条消息？其他成员仍可看到。';if(!confirm(prompt))return;try{if(all){const attachment=entry.payload.attachment?.id||'',query=new URLSearchParams({scope:'all'});if(attachment)query.set('attachment',attachment);await api(`/conversations/${entry.message.conversation_id}/messages/${entry.message.id}?${query}`,{method:'DELETE'})}await LocalHistory.delete(entry.message);state.visibleMessages=state.visibleMessages.filter(m=>Number(m.id)!==Number(entry.message.id));removeMessageElement(entry.message.id);await loadChats();toast(all?'消息已撤回':'已从本机删除')}catch(e){toast(e.message,'error')}}
$('#messageMenu').onclick=async e=>{e.stopPropagation();const action=e.target.closest('[data-message-action]')?.dataset.messageAction,entry=state.contextMessage;if(!action||!entry)return;hideMessageMenu();if(action==='reply')setReplyDraft(entry);else if(action==='forward')showForwardDialog(entry);else if(action==='copy')await copyMessage(entry);else if(action==='delete-self')await deleteSingleMessage(entry,'self');else if(action==='delete-all')await deleteSingleMessage(entry,'all')};
function cleanupDaySeparators(){document.querySelectorAll('#messages .daySeparator').forEach(separator=>{let next=separator.nextElementSibling,found=false;while(next&&!next.classList.contains('daySeparator')){if(next.classList.contains('msg'))found=true;next=next.nextElementSibling}if(!found)separator.remove()});const messages=document.querySelectorAll('#messages .msg'),last=messages[messages.length-1],entry=last&&state.messagePayloads.get(String(last.dataset.messageId));state.lastMessageDay=entry?localDayKey(entry.message.created_at):''}
