function attachMessageInteractions(element,entry){let timer=null,startX=0,startY=0,suppressClick=false;const cancel=()=>{clearTimeout(timer);timer=null};element.addEventListener('contextmenu',event=>showMessageMenu(event.clientX,event.clientY,entry,element,event));element.addEventListener('pointerdown',event=>{if(event.pointerType==='mouse'||event.button!==0)return;startX=event.clientX;startY=event.clientY;cancel();timer=setTimeout(()=>{suppressClick=true;showMessageMenu(startX,startY,entry,element);try{navigator.vibrate?.(20)}catch{}},550)});element.addEventListener('pointermove',event=>{if(Math.hypot(event.clientX-startX,event.clientY-startY)>10)cancel()});element.addEventListener('pointerup',cancel);element.addEventListener('pointercancel',cancel);element.addEventListener('click',event=>{if(suppressClick){event.preventDefault();event.stopPropagation();suppressClick=false}},true)}
