async function loadChats(){state.chats=await api('/conversations');const summaries=await LocalHistory.summaries(state.chats.map(chat=>chat.id));for(const chat of state.chats){const local=summaries.get(chat.id);if(local?.latest){chat.last_message=local.latest.body;chat.last_at=local.latest.created_at}chat.unread=Math.max(chat.manual_unread?1:0,local?.unread||0)}if(state.active&&!document.hidden){const active=state.chats.find(x=>x.id===state.active);if(active&&!active.manual_unread)active.unread=0}state.chats.sort((a,b)=>Number(b.pinned)-Number(a.pinned)||(new Date(b.last_at||0)-new Date(a.last_at||0)));refreshUnreadIndicators();renderChats(state.sideView==='chats'?$('#search').value:'')}
