function dayLabel(value){const d=new Date(value),now=new Date(),today=new Date(now.getFullYear(),now.getMonth(),now.getDate()),day=new Date(d.getFullYear(),d.getMonth(),d.getDate()),days=Math.round((today-day)/86400000),week=d.toLocaleDateString('zh-CN',{weekday:'short'});if(days===0)return '今天';if(days===1)return `昨天 · ${week}`;if(d.getFullYear()===now.getFullYear())return `${d.getMonth()+1}月${d.getDate()}日 · ${week}`;return `${d.getFullYear()}年${d.getMonth()+1}月${d.getDate()}日 · ${week}`}
