async function renderVisibleMessages(preserveTop=false){const box=$('#messages'),oldHeight=box.scrollHeight,oldTop=box.scrollTop;revokeMessageImages();box.innerHTML='';state.messagePayloads.clear();state.lastMessageDay='';if(state.historyLoading||!state.historyDone){const status=document.createElement('div');status.className='historyStatus';status.textContent=state.historyLoading?'正在读取本地历史…':'上滑加载更早的本地消息';box.appendChild(status)}for(const message of state.visibleMessages)await addMessage(message,{persist:false,scroll:false});if(preserveTop)box.scrollTop=box.scrollHeight-oldHeight+oldTop}
async function loadOlderMessages(){if(state.historyLoading||state.historyDone||!state.active)return;state.historyLoading=true;const conversationID=state.active,oldHeight=$('#messages').scrollHeight,oldTop=$('#messages').scrollTop;try{const page=await LocalHistory.page(conversationID,state.historyCursor);if(state.active!==conversationID)return;if(page.length){state.historyCursor=page[0].sort;state.visibleMessages=[...page.map(item=>item.message),...state.visibleMessages];state.historyDone=page.length<LocalHistory.PAGE}else state.historyDone=true;await renderVisibleMessages(false);$('#messages').scrollTop=$('#messages').scrollHeight-oldHeight+oldTop}catch(e){console.warn('local history load failed',e);toast('读取本地历史失败','error')}finally{state.historyLoading=false;document.querySelector('#messages .historyStatus')?.replaceChildren(document.createTextNode(state.historyDone?'已到本地记录起点':'上滑加载更早的本地消息'))}}
