document.addEventListener('keydown',e=>{if(e.key==='Escape'){hideImageViewer();hideConversationMenu();hideMessageMenu();$('#emojiPanel').hidden=true}});
document.addEventListener('click',e=>{if(!e.target.closest('#conversationMenu'))hideConversationMenu();if(!e.target.closest('#messageMenu')&&!e.target.closest('.msg'))hideMessageMenu();if(!$('#emojiPanel').hidden&&!e.target.closest('#emojiPanel')&&!e.target.closest('#emojiToggle'))$('#emojiPanel').hidden=true});
document.addEventListener('contextmenu',e=>{if(!e.target.closest('.chat')&&!e.target.closest('#conversationMenu'))hideConversationMenu();if(!e.target.closest('.msg')&&!e.target.closest('#messageMenu'))hideMessageMenu()});$('#chats').addEventListener('scroll',hideConversationMenu);$('#messages').addEventListener('scroll',()=>{hideMessageMenu();if($('#messages').scrollTop<48)loadOlderMessages()});window.addEventListener('resize',()=>{hideConversationMenu();hideMessageMenu()});
$('#forwardDialog').addEventListener('close',()=>{state.forwardMessage=null});
async function deleteConversation(id){if(!confirm('确定从列表中删除这段对话？'))return;try{await api(`/conversations/${id}`,{method:'DELETE'});if(state.active===id){state.active=null;state.members=[];$('#app').classList.remove('mobile-room-open');$('#room').hidden=true;$('#empty').hidden=false}await loadChats();toast('对话已删除')}catch(e){toast(e.message,'error')}}
async function showSystemNotification(title,body,conversationID,tag=`conversation-${conversationID||'system'}`){if(!('Notification'in window)||Notification.permission!=='granted')return false;const data={url:conversationID?`/?conversation=${conversationID}`:'/',conversation_id:conversationID};try{if('serviceWorker'in navigator){const registration=await navigator.serviceWorker.ready;await registration.showNotification(title,{body,tag,renotify:false,icon:'/assets/icon.svg',badge:'/assets/icon.svg',data});return true}const notification=new Notification(title,{body,tag,icon:'/assets/icon.svg',data});notification.onclick=()=>{window.focus();if(conversationID)openRoom(conversationID);notification.close()};return true}catch(e){console.warn('system notification failed',e);return false}}
async function notifyMessage(m){const chat=state.chats.find(x=>x.id===m.conversation_id);if(m.sender_id===state.me.id||chat?.muted||(!document.hidden&&state.active===m.conversation_id))return;try{const members=state.active===m.conversation_id?state.members:await api(`/conversations/${m.conversation_id}/members`),payload=await E2EE.decryptPayload(m.body,m.conversation_id,state.me.id,members,m.sender_id),body=payload.body||(payload.attachment?'📷 图片':'新消息');toast(`${m.sender_name}：${body}`);await showSystemNotification(m.sender_name,body,m.conversation_id)}catch(e){console.warn('notification failed',e)}}
async function handleSocketEvent(x){if(x.type==='message'){const chat=state.chats.find(item=>item.id===x.data.conversation_id);if(chat)chat.archived=false;await addMessage(x.data);await notifyMessage(x.data);if(state.active===x.data.conversation_id&&!document.hidden)scheduleConversationRead(x.data.conversation_id);else await loadChats()}else if(x.type==='friendship'){await loadFriends();toast(x.action==='requested'?'收到新的好友申请':'好友列表已更新')}else if(x.type==='conversation'){if(x.action==='cleared'){await LocalHistory.clear(x.conversation_id);if(state.active===x.conversation_id){revokeMessageImages();$('#messages').innerHTML='';state.messagePayloads.clear();state.visibleMessages=[];state.historyDone=true;clearReplyDraft();hideMessageMenu();state.lastMessageDay=''}}if(x.action==='message_deleted'){const removed=x.scope==='all'?await LocalHistory.deleteIfSender(x.conversation_id,x.message_id,x.actor_id):x.actor_id===state.me.id;if(removed){state.visibleMessages=state.visibleMessages.filter(message=>Number(message.id)!==Number(x.message_id));if(state.active===x.conversation_id)removeMessageElement(x.message_id)}}await loadChats();if(x.action==='cleared'&&x.actor_id!==state.me.id)toast('对方已清除双方聊天记录');if(x.action==='message_deleted'&&x.scope==='all'&&x.actor_id!==state.me.id)toast('对方撤回了一条消息')}}
function renderConnectionStatus(){const el=$('#room header small');if(!el)return;const labels={connected:'已连接',connecting:'连接中',reconnecting:'重连中',offline:'网络已断开'},status=labels[state.connectionState]||labels.reconnecting;el.textContent=`${state.securityLabel||'🔒 端到端加密'} · ${status}`;el.dataset.state=state.connectionState==='connected'?'connected':state.connectionState==='offline'?'offline':'connecting'}
function scheduleReconnect(){clearTimeout(state.reconnectTimer);if(!state.token||!navigator.onLine){state.connectionState='offline';renderConnectionStatus();return}state.connectionState='reconnecting';renderConnectionStatus();const delay=Math.min(30000,1000*2**Math.min(state.reconnectAttempt,5))+Math.floor(Math.random()*500);state.reconnectAttempt++;state.reconnectTimer=setTimeout(connect,delay)}
function connect(){clearTimeout(state.reconnectTimer);if(!state.token||!navigator.onLine){state.connectionState='offline';renderConnectionStatus();return}if(state.ws&&(state.ws.readyState===WebSocket.OPEN||state.ws.readyState===WebSocket.CONNECTING))return;state.connectionState=state.wsEverConnected?'reconnecting':'connecting';renderConnectionStatus();const scheme=location.protocol==='https:'?'wss':'ws';let ws;try{ws=new WebSocket(`${scheme}://${location.host}/ws?token=${encodeURIComponent(state.token)}`)}catch{scheduleReconnect();return}state.ws=ws;ws.onopen=async()=>{if(state.ws!==ws)return;const reconnected=state.wsEverConnected;state.wsEverConnected=true;state.reconnectAttempt=0;state.connectionState='connected';renderConnectionStatus();if(reconnected){toast('连接已恢复');await loadChats().catch(()=>{});if(state.active)openRoom(state.active).catch(e=>toast(e.message,'error'))}};ws.onmessage=async e=>{let x;try{x=JSON.parse(e.data)}catch{return}await handleSocketEvent(x)};ws.onerror=()=>ws.close();ws.onclose=()=>{if(state.ws!==ws)return;state.ws=null;scheduleReconnect()}}
function updateAppBadge(unread){if('setAppBadge'in navigator){if(unread)navigator.setAppBadge(unread).catch(()=>{});else navigator.clearAppBadge().catch(()=>{})}const old=document.querySelector('link[data-badge]');if(old)old.remove();if(!unread){window.signalDesktop?.setBadge(0,'');return}const canvas=document.createElement('canvas');canvas.width=64;canvas.height=64;const x=canvas.getContext('2d');x.fillStyle='#e53935';x.beginPath();x.arc(32,32,30,0,Math.PI*2);x.fill();x.fillStyle='#fff';x.font='bold 30px system-ui';x.textAlign='center';x.textBaseline='middle';x.fillText(unread>99?'99+':String(unread),32,33);const link=document.createElement('link');link.rel='icon';link.dataset.badge='1';link.href=canvas.toDataURL();document.head.appendChild(link);window.signalDesktop?.setBadge(unread,link.href)}
if('serviceWorker'in navigator){navigator.serviceWorker.register('/sw.js').then(registration=>registration.update()).catch(()=>{});navigator.serviceWorker.addEventListener('message',e=>{if(e.data?.type==='open-conversation'&&e.data.conversation_id)openRoom(Number(e.data.conversation_id))})}
function showConversationList(){state.active=null;clearReplyDraft();hideMessageMenu();$('#app').classList.remove('mobile-room-open');loadChats()}
$('#mobileBack').onclick=showConversationList;
document.addEventListener('visibilitychange',()=>{if(!document.hidden){connect();if(state.active)scheduleConversationRead(state.active);if('Notification'in window&&Notification.permission==='granted'&&!state.pushEnabled)syncPushSubscription().catch(()=>{})}});
window.addEventListener('online',()=>{state.reconnectAttempt=0;connect()});window.addEventListener('offline',()=>{state.connectionState='offline';renderConnectionStatus()});
function syncViewport(){const height=window.visualViewport?.height||window.innerHeight;document.documentElement.style.setProperty('--app-height',`${height}px`)}
syncViewport();window.visualViewport?.addEventListener('resize',syncViewport);window.addEventListener('orientationchange',syncViewport);
function updateNotificationButton(){const button=$('#notifications');if(!button)return;const permission='Notification'in window?Notification.permission:'unsupported',enabled=permission==='granted';button.textContent=enabled?'●':'♢';button.classList.toggle('enabled',enabled);button.classList.toggle('blocked',permission==='denied');button.title=permission==='granted'?(state.pushEnabled?'后台消息通知已开启':'系统通知已允许，正在连接后台推送'):permission==='denied'?'通知已被浏览器阻止，请在网站设置中允许':'开启后台消息通知'}
async function enableNotifications(){if(!('Notification'in window)||!('serviceWorker'in navigator)||!('PushManager'in window)){toast('当前环境不支持后台推送；iPhone 请先“添加到主屏幕”后再开启','error');return}if(Notification.permission==='denied'){updateNotificationButton();toast('通知已被浏览器阻止，请在地址栏的网站设置中改为“允许”','error');return}const permission=Notification.permission==='granted'?'granted':await Notification.requestPermission();updateNotificationButton();if(permission!=='granted'){toast('未获得通知权限，请点击通知图标重试','error');return}try{const enabled=await syncPushSubscription();if(!enabled){toast('服务器后台推送尚未配置','error');return}await showSystemNotification('Signal Web','后台消息通知已开启；浏览器最小化后仍会提醒。',null,'notification-ready');toast('后台消息通知已开启')}catch(e){state.pushEnabled=false;updateNotificationButton();toast('推送开启失败：'+e.message,'error')}}
let deferredInstallPrompt=null;function isStandalone(){return window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true}function updateInstallButton(){const button=$('#installApp');if(button)button.hidden=isStandalone()}window.addEventListener('beforeinstallprompt',event=>{event.preventDefault();deferredInstallPrompt=event;updateInstallButton()});window.addEventListener('appinstalled',()=>{deferredInstallPrompt=null;updateInstallButton();toast('已安装到桌面，可固定到任务栏运行')});$('#installApp').onclick=async()=>{if(isStandalone()){toast('当前已经是独立应用模式');return}if(deferredInstallPrompt){await deferredInstallPrompt.prompt();const choice=await deferredInstallPrompt.userChoice;deferredInstallPrompt=null;if(choice.outcome!=='accepted')toast('已取消安装');return}const isiOS=/iPad|iPhone|iPod/.test(navigator.userAgent);toast(isiOS?'请点浏览器“分享”，选择“添加到主屏幕”':'请打开浏览器菜单，选择“安装 Signal Web”或“创建快捷方式”','error')};updateInstallButton();
$('#notifications').onclick=enableNotifications;updateNotificationButton();
document.querySelectorAll('[data-side-view]').forEach(x=>x.onclick=()=>setSideView(x.dataset.sideView));
$('#search').oninput=e=>state.sideView==='friends'?renderFriends(e.target.value):renderChats(e.target.value);
let friendSearchTimer;$('#friendSearch').oninput=e=>{clearTimeout(friendSearchTimer);friendSearchTimer=setTimeout(()=>searchUsers(e.target.value).catch(err=>toast(err.message,'error')),220)};
$('#addFriend').onclick=()=>{$('#friendSearch').value='';$('#friendResults').innerHTML='<div class="listEmpty">输入信息开始查找</div>';$('#friendDialog').showModal();setTimeout(()=>$('#friendSearch').focus(),50)};
$('#profileButton').onclick=()=>{$('#profileUsername').value='@'+state.me.username;$('#profileDisplay').value=state.me.display_name;$('#profileAbout').value=state.me.about||'';$('#profileDialog').showModal()};
$('#saveProfile').onclick=async()=>{try{await api('/me/profile',{method:'PUT',body:JSON.stringify({display_name:$('#profileDisplay').value,about:$('#profileAbout').value})});state.me.display_name=$('#profileDisplay').value.trim();state.me.about=$('#profileAbout').value.trim();renderMyProfile();$('#profileDialog').close();toast('个人资料已保存')}catch(e){toast(e.message,'error')}};
$('#logout').onclick=()=>{localStorage.removeItem('token');location.reload()};
$('#newGroup').onclick=()=>{if(!state.friends.length){toast('请先添加好友','error');setSideView('friends');return}$('#groupUsers').innerHTML=state.friends.map(u=>`<label class="pick"><input type="checkbox" value="${u.id}"> ${esc(u.display_name)} (@${esc(u.username)})</label>`).join('');$('#groupDialog').showModal()};
$('#createGroup').onclick=async()=>{const ids=[...document.querySelectorAll('#groupUsers input:checked')].map(x=>+x.value);try{const x=await api('/conversations',{method:'POST',body:JSON.stringify({name:$('#groupName').value,member_ids:ids})});$('#groupDialog').close();await loadChats();openRoom(x.id)}catch(e){toast(e.message,'error')}};if(state.token)start().catch(()=>{});
